from tools46 import *
assert not (OWN/'external_failure_stop.json').exists()
def make(q,v,preset,actions,roles,mechanism,proof,difference):
    d=OWN/q/v;d.mkdir(parents=True,exist_ok=False)
    e=eligibility(q);save(d/'eligibility_before_design.json',e);assert e['eligible']
    save(d/'design_difference_audit.json',{'question_id':q,'variant_id':v,'created_at':now(),'old_history_audit':str(OWN/q/'full_old_history_read_46.json'),'old_history_sha256':sha(OWN/q/'full_old_history_read_46.json'),'substantive_difference':difference,'genuinely_new_design':True,'not_recolor_width_crop_rename_or_posthoc_preset':True,'wrong_answer_frozen_before_any_call':preset,'old_observed_outputs_not_chased':True,'old_original_controls_reused_without_new_calls':[]})
    ctx=AD.inspect_question(q);save(d/'context.json',ctx);pr=PluginRenderer(CONFIG,AD,{q:ctx})
    plugin=pr.normalize({'plugin_schema_version':'1.0.0','question_id':q,'category':'C','operation':'C_manual','description':mechanism,'intent':mechanism,'params':{'actions':actions}})
    save(d/'plugin.json',plugin);assert pr.normalize(plugin)==plugin
    bindings=paths(q,[a['target'] for a in actions]);save(d/'marker_path_bindings.json',bindings)
    before=inputs(q);s=AD.scene(q)
    try:
        no,pix=scene_png(s);(d/'noop.png').write_bytes(no);assert pix==pixel_hash(AD.original_paths[q])
        s.fig.canvas.draw();snap=artist_snapshot(s);pr.apply_actions(s,plugin);s.fig.canvas.draw();assert snap==artist_snapshot(s)
    finally:s.close()
    replays=[]
    for i in [1,2]:
        _,b,ph=pr.render(plugin);path=d/('candidate.png' if i==1 else 'offline_replay_2.png');path.write_bytes(b);replays.append({'path':str(path),'sha256':sha(path),'pixel_sha256':ph})
    assert (d/'candidate.png').read_bytes()==(d/'offline_replay_2.png').read_bytes()
    assert before==inputs(q)
    om={o['id']:o for o in ctx['objects']}
    mark=[{'index':i,'action':a,'specific_source_receiver_role':r,'actual_frozen_object':om[a['target']]} for i,(a,r) in enumerate(zip(actions,roles))]
    save(d/'render_check.json',{'schema_valid':True,'normalization_idempotent':True,'no_op_pixel_equals_current_formal':True,'two_offline_draws_byte_and_pixel_equal':True,'replays':replays,'fills_text_view_exactly_unchanged':True,'original_input_hashes_before_and_after_equal':True,'frozen_inputs':before,'environment':environment_versions(),'isolation':ISOLATION,'strict_own_directory_write_guard_installed_before_project_imports':True,'appearance_changes':pr.appearance_changes(plugin)})
    save(d/'design.json',{'question_id':q,'variant_id':v,'created_at':now(),'expected_wrong_answer':preset,'formal_correct_answer':AD.records[q]['answer'],'mechanism':mechanism,'primary_math_proof':proof,'per_mark_roles':mark,'candidate_png_sha256':sha(d/'candidate.png'),'plugin_sha256':sha(d/'plugin.json'),'path_bindings_sha256':sha(d/'marker_path_bindings.json'),'difference_audit_sha256':sha(d/'design_difference_audit.json'),'substantive_math_audit':str(OWN/q/'substantive_math_audit_46.json'),'substantive_math_audit_sha256':sha(OWN/q/'substantive_math_audit_46.json'),'status':'FROZEN_BEFORE_CALLS; requires native primary review','limitations':['No effectiveness claim before pair.','No causal-gain or narrative-consistency gate.','A pair hit only creates a primary possibility pending parent NEW independent second review.']})
    print(q,v,'frozen preset',preset,'PNG',sha(d/'candidate.png'),flush=True)
q='Solid104';audit=read(OWN/q/'substantive_math_audit_46.json');edges=audit['chosen_true_shared_edges']
acts=[{'type':'set_object_style','target':x['target'],'color':x['color'],'linewidth_pt':2} for x in edges]
roles=['Actual shared boundary of central white square'+str(x['receiver_square_face'])+' and '+('pentagonal' if x['adjacent_face_sides']==5 else 'triangular')+' face'+str(x['adjacent_face_index'])+'. Color identifies the contact type; this is one side-incidence record, not a separate square.' for x in edges]
make(q,'r46_square_contact_records_to_faces','40',acts,roles,'Separate the central square four actual side contacts into two pentagon contacts and two triangle contacts, testing substitution of pentagon-square contact records for distinct square faces.',{'correct_derivation':audit['correct_derivation'],'wrong_derivation':audit['wrong_predeclared_derivation'],'exact_graph_check':'60vertices/120edges,12pentagons/30squares/20triangles; each square borders two pentagons and two triangles.','human_uniqueness':'All four colored boundaries enclose one unchanged white square, with two actual adjacent pentagons and two actual triangles. Color labels a contact category, not a new numerical label/equality/face or a changed fill. The original legend stays intact and unique sum50 remains available.'},'Old15 prescreen only considered confusing different polygon/fill categories in the legend and rejected it; old40 exact census was preliminary. This new four-edge local incidence representation preserves all face/legend classifications, and tests a specific two-to-one incidence/face confusion with predeclared40. No prior104 candidate PNG or call existed.')
q='Solid189';acts=[{'type':'set_object_style','target':t,'color':'#DC2626','linewidth_pt':2} for t in ['towere53','towere55','planedge57','planedge58']]
roles=['Peak central light-column top front edge x0..1,y0,z4: source of actual height4.','Peak central light-column top left edge x0,y0..1,z4: completes source open corner without touching fill.','Right boundary of outerlight plan cell(2,0), screen-data x9.95,y0.65..1.35; receiver is actual height2 column.','Top boundary of same outerlight plan cell(2,0), screen-data y1.35,x9.25..9.95; completes receiving open corner.']
make(q,'r46_peak_height_to_outer_light_column','22',acts,roles,'Pair the true four-high central peak top corner in side view with one actual two-high outer light-column plan corner, testing transfer of peak height to that outer column.',{'correct_derivation':'25monochromatic columns have heights4-|x|-|y| over |x|+|y|<=3. Light columns are center(0,0)height4 plus8distance2 columnsheight2; sum4+8*2=20. Independently verified all44source blocks,25columns and color membership.','wrong_derivation':'Transfer source central peak height4 to exactly the marked outerlight plan column(2,0)height2, retaining center4 and other7outerheight2:4+7*2+4=22.','human_uniqueness':'The genuine peak remains central in the side view and the receiver lies two plan cells from the center. All black/white fills, monochromatic columns, original layers and separate column multiplicity remain. Matching red outlines are comparison annotations without an equality or relocation symbol; actual geometry uniquely20.','true_column_mapping':'Plan centers have screen-data (8.2+0.7x,1+0.7y). Receiver(2,0) is (9.6,1), bounds[9.25,9.95]x[0.65,1.35]. Side source is top of column(0,0) atz4.'},'Old16 paired central planedges34/35 to peripheral side edges10/12, transferring height2 into the center, preset18 and finals9/32. New design instead uses central peak side53/55 as height4 source and outerlight plan57/58 as receiver(2,0), predeclaring22. Both selected source feature and receiving true column change; it is not a color/width/PNG rename or relabeling of observed outputs.')
